CREATE OR REPLACE FUNCTION public.can_moderate_memorial(_memorial_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO public AS $$ SELECT EXISTS (SELECT 1 FROM public.memorials WHERE id = _memorial_id AND owner_id = auth.uid()) OR COALESCE(public.memorial_role(_memorial_id, auth.uid()) IN ('owner','admin'),false) OR public.has_role(auth.uid(),'admin'); $$; CREATE OR REPLACE FUNCTION public.is_memorial_owner(_memorial_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO public AS $$ SELECT EXISTS (SELECT 1 FROM public.memorials WHERE id = _memorial_id AND owner_id = auth.uid()) OR COALESCE(public.memorial_role(_memorial_id, auth.uid()) = 'owner',false); $$; INSERT INTO public.memorial_managers(memorial_id,user_id,role) SELECT m.id,m.owner_id,'owner' FROM public.memorials m WHERE NOT EXISTS(SELECT 1 FROM public.memorial_managers mm WHERE mm.memorial_id=m.id AND mm.user_id=m.owner_id) ON CONFLICT DO NOTHING; DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.memorials) THEN RETURN; END IF; END $$;